from pathlib import Path
import base64, json, hashlib
p=Path(__file__).parent
library_source=p/'training/approved-expanded.jsonl'
library_rows=[json.loads(line) for line in library_source.read_text().splitlines() if line.strip()]
library_entries=[{'id':r['id'],'group':r['group'],'title':r['scene']['title'],'scene':r['scene'],'physicallyTested':r.get('physically_tested') is True} for r in library_rows if r.get('reviewed') is True and r.get('training_consent') is True and r.get('scene_validated') is True and r['group']!='fish']
if len({r['group'] for r in library_entries})!=len(library_entries):
    raise ValueError('Example groups must be unique.')
library={'sourceSha256':hashlib.sha256(library_source.read_bytes()).hexdigest(),'entries':library_entries}
payload=json.dumps(library,separators=(',',':'),ensure_ascii=True).replace('<','\\u003c')
p.joinpath('parts-library.js').write_text("// Generated by build.py from existing reviewed synthetic scenes.\n(function(root){'use strict';const library="+payload+";library.get=group=>{const row=library.entries.find(r=>r.group===group);return row?JSON.parse(JSON.stringify(row.scene)):null;};root.BeadPartsLibrary=library;if(typeof module!=='undefined')module.exports=library;})(typeof window!=='undefined'?window:globalThis);\n")
s=p.joinpath('shell.html').read_text()
for label,filename in [('STYLE','style.css'),('VOLUME_STYLE','volume-style.css'),('ENGINE','engine.js'),('APP','app.js'),('SHAPE_ENGINE','shape-engine.js'),('VOLUME_ENGINE','volume-engine.js'),('THREAD_DIAGRAM','thread-diagram.js'),('STAGE_GUIDE','stage-guide.js'),('PEYOTE_BALL','peyote-ball.js'),('CRAW_BLOCK','craw-block.js'),('PARTS_LIBRARY','parts-library.js'),('CONSTRUCTION_GRAPH','construction-graph.js'),('PARTS_ENGINE','parts-engine.js'),('BEAD_GEOMETRY','bead-geometry.js'),('CONTINUOUS_THREAD','continuous-thread.js'),('THREAD_FINISHING','thread-finishing.js'),('FINISHING_GUIDE','finishing-guide.js'),('PARTS_LAYOUT','parts-layout.js'),('PARTS_APP','parts-app.js'),('PARTS_PROJECT','parts-project.js'),('VOLUME_APP','volume-app.js'),('CREATOR_APP','creator-app.js'),('CONNECTION_APP','connection-app.js'),('JOURNEY_APP','journey-app.js'),('FINISHED_APP','finished-app.js'),('PLAYFUL_APP','playful-app.js'),('FLOAT_PHYSICS','float-physics.js'),('SHAPE_REFERENCE','shape-reference.js'),('MAKER_TOOLS','maker-tools.js'),('PATTERN_SOURCES','pattern-sources.js')]:
    s=s.replace('/*'+label+'*/',p.joinpath(filename).read_text())
s=s.replace('<!--VOLUME_HTML-->',p.joinpath('volume-shell.html').read_text())
names=['frog','caterpillar','blue-lizard','jellyfish','starfish','crocodile']
assets=[{'name':name,'src':'data:image/webp;base64,'+base64.b64encode(p.joinpath('assets',name+'.webp').read_bytes()).decode()} for name in names]
s=s.replace("['frog','caterpillar','blue-lizard','jellyfish','starfish','crocodile'].map(name=>({name,src:'assets/'+name+'.webp'}))",json.dumps(assets))
p.joinpath('beadform.html').write_text(s)
print('Built beadform.html:',len(s.encode()),'bytes')
